/*
 * 올인 러브 — 연서 루트 3~4주차 (Day 15~28) + 연서 엔딩 5종 + 반성회 (v3 개편)
 * 개편안: 프로젝트 claude/2026-10-23-love-v3-design.md · 기준 대본 script-w1.ts
 *
 * 3주차(y3_*) : 쪽지/침묵 → 비상계단 해명 → 사장의 아래층 딜러 제안 · [큰 결정] 지하 문 → 오피스텔 고백(벽, "가지 마요")
 *              → 비품 창고에서 듣는 거짓 보고 → 장갑 벗기 · 빨간 볼펜 → (affY 17↑) 여름 바다 / 김치찌개 · 바다 사진 → 에이미 아빠 사진
 * 4주차(y4_*) : 사장의 최후통첩 → 정민의 5년 치 노트 → D24 진실(5년 전 워커 씨 테이블) · [큰 결정]
 *              → 지하에서 카드를 덮은 밤 · 첫 웃음 → 반쯤 빈 방, 편도표 → D28 새벽, 3년 만의 자리 → 엔딩
 * 매일: 설렘 또는 웃음 한 번(태양 · 정민 · 이모 · 에이미) + 밤 메신저(연서). 번호가 없던 경로는 D15 비상계단에서 받음(yeonNum)
 *
 * 1주차에서 읽는 것(조건부): yeonCat 콜 · yeonHide 비품 창고 · yeonGlove 흉터 얘기 · knowY 두 번 두드리기 텔 · boxOpen 7_94
 *   vipDigits 닳은 숫자 · imoKnow 빨대 청년 · imoClue 워커 씨 · imoCook 두부 · amyDad 아빠 행선지 · yeonNum 번호 · skill
 * 2주차에서 읽는 것(이름 유지 가정): yeonNote 쪽지 · yeonRisk 보너스 돌려줌 · yeonScar 흉터 봄+약속 · yeonName 이름 · 동그라미
 *   yeonHome 오피스텔 가 봄 · yeonEnvelope 2 = 에이미한테 봉투 직접 줌
 *   n2Join 2(아무도→연서: 12일차 오피스텔 · 동그라미는 봤지만 yeonHome 없음) · yCircles 2주차 동그라미 수(D16 · D19에서 +1)
 *   y2Stew(w2_i2_y 에서 그가 끓인 찌개를 먹음) · yMatch(9일차 성냥갑 받음 → D28 승리 뒤 회수)
 * 새 수치: vipOpen · riskY · vipDealer · rigKnow(+meta_rigKnow) · twoTimer · yeonJealous · yeonPen · yeonSea · yeonLedger · yeonRun
 *          yeonAlone · yeonAmy · yAmyCall · yJmNote · yCircle(3주차에 동그라미를 처음 정함) · yPromise(D15 "안 받아요")
 *          knowCode(문 번호를 맞힘) · yRound(왕복표 약속) · yDealt(D28 연서가 딜링) · yGoSt(첫차 배웅 간다고 답함) · yNew(D15에 번호 받음)
 * 엔딩 판정(D28): tilt≥7 me_fall → vipDealer dealer → clash(affA·affY≥8 & twoTimer≥2) → yeonAlone sad → riskY≥6 vanish → 테이블
 *   이김 + ★(meta_ledger · yeonLedger · yAmyCall, 레일 밑 아빠 공책) → true / 이김 + 독점(affY≥18 · trustY≤9 · yeonJealous≥2) → obsess
 *   / 이김 → good / 짐 · 폴드 → sad
 */
import { A, BOSS, CH, FACE, JM, ME, MONTAGE, N, PLAN, TH, TIMED, TY, Y, card, match, poker } from "./dsl";
import type { MatchSpec, PokerSpec, Scenes } from "./types";

